SELECT ?sensor ?class ?ts WHERE {
  ?zone a brick:Zone ; rdfs:label "Perimeter_mid_ZN_3".
  ?sensor a ?class ; brick:hasInputLocation ?zone .
  ?sensor ref:hasTimeseriesId ?ts .
  FILTER(contains(str(?class), "ElectricPower") || contains(str(?class), "Occupancy"))
}

SELECT ?sensor ?class ?ts WHERE {
  ?zone a brick:Zone ; rdfs:label "Perimeter_mid_ZN_3".
  ?sensor brick:hasInputLocation ?zone .
  OPTIONAL {?sensor ref:hasTimeseriesId ?ts}
  a ?class .
} LIMIT 100

SELECT ?sensor ?class ?ts WHERE {
  ?zone a brick:Zone ; rdfs:label "Perimeter_mid_ZN_3".
  ?sensor brick:hasInputLocation ?zone .
  ?sensor a ?class .
  OPTIONAL {?sensor ref:hasTimeseriesId ?ts}
} LIMIT 100

SELECT ?point ?class ?ts WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z02> brick:hasPoint ?point .
  ?point a ?class .
  OPTIONAL {?point ref:hasTimeseriesId ?ts}
}

SELECT ?point ?pred ?obj WHERE {
  ?z a brick:Zone ; rdfs:label "Perimeter_mid_ZN_3" .
  ?z brick:hasPoint ?point .
  ?point ?pred ?obj .
  FILTER(?pred != rdf:type)
}
